package com.example.demo.controller;

import com.example.demo.entity.*; import com.example.demo.repository.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderRepository orders; private final ProductRepository products; public OrderController(OrderRepository o,ProductRepository p){orders=o;products=p;} @GetMapping public List<Order> mine(Authentication a){return orders.findByCustomerEmailOrderByCreatedAtDesc(a.getName());} @GetMapping("/{id}") public Order one(@PathVariable Long id,Authentication a){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(!o.getCustomerEmail().equals(a.getName()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return o;} @PostMapping public ResponseEntity<Order> create(@Valid @RequestBody CreateOrder r,Authentication a){Order o=new Order();o.setCustomerEmail(a.getName());BigDecimal total=BigDecimal.ZERO;for(Line l:r.items()){Product p=products.findById(l.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(p.getStock()<l.quantity())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Insufficient stock");p.setStock(p.getStock()-l.quantity());OrderItem i=new OrderItem();i.setOrder(o);i.setProduct(p);i.setQuantity(l.quantity());i.setUnitPrice(p.getPrice());o.getItems().add(i);total=total.add(p.getPrice().multiply(BigDecimal.valueOf(l.quantity())));products.save(p);}o.setTotal(total);return ResponseEntity.status(201).body(orders.save(o));} public record CreateOrder(@NotEmpty List<@Valid Line> items){} public record Line(@NotNull Long productId,@Min(1) int quantity){} }
